INSERT INTO `obo_doc_checklist` VALUES ('A01','ARCHITECTURAL','ARCHITECTURAL',10,'Needed requirements {s} before {d}','REQUIREMENTS',NULL,0,'ACTIVE'),('FSC01','FSEC_CHECKLIST','FSEC_CHECKLIST',1,'Building exits must abut a public street or approved alley. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC02','FSEC_CHECKLIST','FSEC_CHECKLIST',2,'Provide at least two (2) means of egress for each floor, room. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC03','FSEC_CHECKLIST','FSEC_CHECKLIST',3,'Provide secondary stair/exit as far/remote from main stair/entrance/exit, to serve _the whole area__. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC04','FSEC_CHECKLIST','FSEC_CHECKLIST',4,'Enclose all stairways and fire escapes with walls having {n} hours of fire resistance with access thru self-closing fire doors. ','MEANS OF EGRESS ','d',1,'INACTIVE'),('FSC05','FSEC_CHECKLIST','FSEC_CHECKLIST',5,'Provide two (2) doors as exit ways from all rooms. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC06','FSEC_CHECKLIST','FSEC_CHECKLIST',6,'Interconnect stairs and fire escapes with fire resistive passageways on corridors at least {n} meters wide. ','MEANS OF EGRESS ','d',1,'INACTIVE'),('FSC07','FSEC_CHECKLIST','FSEC_CHECKLIST',7,'Enclose walls, doors, stairs ramps, escalators and other components of exits systems. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC08','FSEC_CHECKLIST','FSEC_CHECKLIST',8,'Provide protected/enclosed horizontal exits with self-closing fire doors. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC09','FSEC_CHECKLIST','FSEC_CHECKLIST',9,'Travel distance to an exit shall not be more than {n}  meters. ','MEANS OF EGRESS','d',1,'INACTIVE'),('FSC10','FSEC_CHECKLIST','FSEC_CHECKLIST',10,'Exit doors shall swing in the direction of exit travel. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC11','FSEC_CHECKLIST','FSEC_CHECKLIST',11,'Revolving doors shall not be used as means of egress except {s}','MEANS OF EGRESS ','s',1,'INACTIVE'),('FSC12','FSEC_CHECKLIST','FSEC_CHECKLIST',12,'Exit door should have a minimum width of 71 cm and a maximum width 122 cm and shall not restrict the opening. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC13','FSEC_CHECKLIST','FSEC_CHECKLIST',13,'Exit door/s should be openable from the inside without the use of keys, special knowledge or effort flush bolts or surface bolts are prohibited. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC14','FSEC_CHECKLIST','FSEC_CHECKLIST',14,'A floor or landing is required not less than the width of exit door. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC15','FSEC_CHECKLIST','FSEC_CHECKLIST',15,'Door should be not project into the required corridor width when fully opened so as not to reduced the corridor width to less than 76.17 cm. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC16','FSEC_CHECKLIST','FSEC_CHECKLIST',16,'Exit doors should provide immediate access to an approved means of egress. Exiting through a bathroom, bedroom or other room subject to locking does not comply. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC17','FSEC_CHECKLIST','FSEC_CHECKLIST',17,'Corridors should have a minimum width of {n} meters. ','MEANS OF EGRESS ','d',1,'INACTIVE'),('FSC18','FSEC_CHECKLIST','FSEC_CHECKLIST',18,'Required corridors in {s} occupancies shall have 2.43 meters (8 ft) minimum width. ','MEANS OF EGRESS ','s',1,'INACTIVE'),('FSC19','FSEC_CHECKLIST','FSEC_CHECKLIST',19,'Dead-end corridors and exit balconies is limited to 6.08 m (20 ft). ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC20','FSEC_CHECKLIST','FSEC_CHECKLIST',20,'Aisles in auditorium shall be minimum of {n} meters in width. ','MEANS OF EGRESS ','d',1,'INACTIVE'),('FSC201','FSEC_CHECKLIST','FSEC_CHECKLIST2',1,'Permissible Exit Components: [{b}] Doors /[{b}] Stairs / [{b}]\nSmokeproof enclosures / [{b}] Horizontal exits / [{b} ]\nRamps / [{b}] Exit passageways / [{b}] Escalator and\nmoving walks / [{b}] Fire escape Stair / [{b}] Fire escape\nladder / [{b}] Slide escape / [{b}] Area of refuge / Outside\nStairs','MEANS OF EGRESS',NULL,0,'ACTIVE'),('FSC202','FSEC_CHECKLIST','FSEC_CHECKLIST2',2,'Capacity factor (Means of Egress): {n} mm\n/ person','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC203','FSEC_CHECKLIST','FSEC_CHECKLIST2',3,'Occupant load factor: {n} m² / person','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC204','FSEC_CHECKLIST','FSEC_CHECKLIST2',4,'Common path of travel:\n{i} m (with sprinkler) {i} m (w/o sprinkler)','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC205','FSEC_CHECKLIST','FSEC_CHECKLIST2',5,'Dead end limit / Corridor:\n{i} m (with sprinkler) {i} m (w/o sprinkler)','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC206','FSEC_CHECKLIST','FSEC_CHECKLIST2',6,'Travel distance:\n{i} m (with sprinkler) {i} m (w/o sprinkler)','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC207','FSEC_CHECKLIST','FSEC_CHECKLIST2',7,'Remoteness of exits:\n{n} m (with sprinkler) {n} m (w/o sprinkler)','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC208','FSEC_CHECKLIST','FSEC_CHECKLIST2',8,'Number of means of egress per floor: {i} /\neach room with occupant load ≥ 50 or with hazard\ncontent:','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC209','FSEC_CHECKLIST','FSEC_CHECKLIST2',9,'Corridor width: {n}  m','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC21','FSEC_CHECKLIST','FSEC_CHECKLIST',21,'Walls and ceilings of corridors should be fire resistive construction materials. ','MEANS OF EGRESS ',NULL,1,'INACTIVE'),('FSC210','FSEC_CHECKLIST','FSEC_CHECKLIST2',10,'Stair width : {n} m','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC211','FSEC_CHECKLIST','FSEC_CHECKLIST2',11,'Ramp width : {n} m','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC212','FSEC_CHECKLIST','FSEC_CHECKLIST2',12,'Any door leaf in a means of egress shall not project more\nthan 180 mm into the required width of an aisle, a\ncorridor, a passageway, or a landing, unless the door leaf\nis equipped with an approved self-closing device.','MEANS OF EGRESS ',NULL,0,'ACTIVE'),('FSC213','FSEC_CHECKLIST','FSEC_CHECKLIST2',13,'Each guest door used as means of egress shall at least\n20 minutes fire resistant','MEANS 