DROP TABLE IF EXISTS `obo_doctype`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `obo_doctype` (
  `objid` varchar(50) NOT NULL,
  `title` varchar(100) DEFAULT NULL,
  `sectionid` varchar(50) DEFAULT NULL,
  `sortorder` smallint(6) DEFAULT NULL,
  `type` varchar(50) DEFAULT NULL,
  `template` varchar(50) DEFAULT NULL,
  `issuetype` int(11) DEFAULT NULL,
  `requirefee` int(11) DEFAULT NULL,
  `controlnopattern` varchar(50) DEFAULT NULL,
  `system` int(11) DEFAULT NULL,
  `role` varchar(50) DEFAULT NULL,
  `endorserid` varchar(50) DEFAULT NULL,
  `approverid` varchar(50) DEFAULT NULL,
  `reportheader` varchar(50) DEFAULT NULL,
  `refdoc` varchar(50) DEFAULT NULL,
  `includeinemail` int(11) DEFAULT NULL,
  `reportid` varchar(50) DEFAULT NULL,
  `code` varchar(50) DEFAULT NULL,
  `version` int(11) DEFAULT NULL,
  `supersededid` varchar(50) DEFAULT NULL,
  `checklistid` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`objid`) USING BTREE,
  KEY `fk_obo_doctype_sectionid` (`sectionid`) USING BTREE,
  KEY `fk_obo_doctype_endorserid` (`endorserid`) USING BTREE,
  KEY `fk_obo_doctype_approverid` (`approverid`) USING BTREE,
  KEY `fk_obo_doctype_role` (`role`) USING BTREE,
  KEY `fk_obo_doctype_reportid` (`reportid`) USING BTREE,
  KEY `fk_obo_doctype_template` (`template`) USING BTREE,
  KEY `code` (`code`) USING BTREE,
  KEY `fk_obo_doctype_checklistid` (`checklistid`) USING BTREE,
  KEY `fk_obo_doctype_refdoc` (`refdoc`) USING BTREE,
  CONSTRAINT `fk_obo_doctype_approverid` FOREIGN KEY (`approverid`) REFERENCES `sys_signature` (`objid`),
  CONSTRAINT `fk_obo_doctype_checklistid` FOREIGN KEY (`checklistid`) REFERENCES `obo_checklist` (`objid`),
  CONSTRAINT `fk_obo_doctype_endorserid` FOREIGN KEY (`endorserid`) REFERENCES `sys_signature` (`objid`),
  CONSTRAINT `fk_obo_doctype_refdoc` FOREIGN KEY (`refdoc`) REFERENCES `obo_doctype` (`objid`),
  CONSTRAINT `fk_obo_doctype_reportid` FOREIGN KEY (`reportid`) REFERENCES `sys_report_def` (`name`),
  CONSTRAINT `fk_obo_doctype_role` FOREIGN KEY (`role`) REFERENCES `sys_role` (`name`),
  CONSTRAINT `fk_obo_doctype_sectionid` FOREIGN KEY (`sectionid`) REFERENCES `obo_section` (`objid`),
  CONSTRAINT `fk_obo_doctype_template` FOREIGN KEY (`template`) REFERENCES `sys_report_template` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

