INSERT INTO `sys_message_template` VALUES ('building_permit_docs','def em = EM.lookup( \"vw_obo_app\" );\ndef docEm = EM.lookup( \"vw_obo_app_doc\" );\ndef app = em.find( [objid: PARAMS.objid] ).first();\napp.email = (!PARAMS.email) ? app.contact.email : PARAMS.email ;\n\ndef svc =  SERVICE.lookup( \"OboAppFindingService\" );\napp.postreqlist = svc.getOpenPostRequirementList( [appid: PARAMS.objid] );\n\n\napp.attachments = docEm.find( [appid: PARAMS.objid]  ).where( \"doctype.includeinemail = 1\" ).list().collect {\n     [  reportid: it.reportid, params: [ objid: it.objid ], title: it.doctype.title, context: \'obo\' ]\n}\nreturn app;','Building Permit ${appno} Completed','Dear ${contact.name}, <br>\nYour building permit application with the ff. has been approved. \n<h1>${appno}</h1>\n\nPlease see advanced copies of permits.<br><br>\n\nYou need to comply the ff. within 90 days\n<ol>\n<% postreqlist.each { o-> %>\n      <li>${o.particulars}</li>\n<% } %>\n</ol>\n\n<br>\nThank you for doing business with OCBO. Please take time to answer our survey to improve our service.\n<a href=\"www.google.com\">Click here to rate</a>','${email}',NULL,'obo-email-server',NULL,'PARAMS.objid = \"BAPP-18112266:18ba451d2b6:-8000\";\nPARAMS.email = \"elmonazareno@gmail.com\";',NULL),('claimstub','def app = EM.lookup( \"vw_obo_app\" ).find( [ objid: PARAMS.objid ] ).first();\napp.email = (!PARAMS.email) ? app.contact.email : PARAMS.email; \napp.attachments = [\n     [reportid: \"claimstub\", params: PARAMS, context: \"obo\", title: app.doctitle + \" Claim Stub\" ] \n];\n\nreturn app;\n\n','${doctitle} App No ${appno}','Dear ${contact.name}, <br><br>\n\nYour ${doctitle} application has been accepted and assigned the \nofficial application number <br> \n\n<h1>${appno}</h1>\n\nPlease see attached file to view the document<br>\n\n\n<br>\nSincerely,\n<br>\n\n<b>The Gensan OSCP Team</b> \n','${email}',NULL,'obo-email-server',NULL,'PARAMS.objid =\"BAPP502a4b92:18121c44dd5:-6f11\";\nPARAMS.email= \"elmonazareno@gmail.com\";',NULL),('inspection_notice','def em = EM.lookup(\"vw_obo_app\" );\ndef app = em.find( [ objid: PARAMS.objid ] ).first();\nif(!app.inspectiondate) throw new Exception(\"Please indicate inspection date\");\n\napp.email = (( PARAMS.email ) ? PARAMS.email : app.contact.email);\nreturn app;\n','Inspection Notice','<% \ndef df = new java.text.SimpleDateFormat( \"MMM dd, yyyy\" );\ndef tf = new java.text.SimpleDateFormat( \" hh:mm aa\" );\n%> \nDear ${contact.name}, <br>\n\nWe will be conducting an inspection on ${df.format( inspectiondate )} at \n${ tf.format( inspectiondate ) }. Please be advised accordingly. <br>\n\n   ','${email}',NULL,'obo-email-server',NULL,'PARAMS.objid = \"BAPP-415accb6:18c85bbe2f3:-7f2c\";\nPARAMS.email = \"elmonazareno@gmail.com\";',NULL),('notice_of_disapproval','def svc = SERVICE.lookup( \"OboAppTransmittalService\" );\ndef trans = svc.findTransmittal( PARAMS ); \ntrans.email = ( PARAMS.email ) ? PARAMS.email : trans.contact.email; \ntrans.emailcopy = \"rameses.systems@gmail.com\";\ntrans.attachments = [\n     [ reportid: \"notice_of_disapproval\", params: [objid: trans.objid], \n          context:\'obo\', title: \'Notice Of Disapproval\' ]\n];\n\nreturn trans;','Notice of Disapproval - ${trackingno}','Dear <b>${contact.name}</b>, <br>\n\n<br>\nThis has reference to your application for ${doctitle} with tracking no ${trackingno} with our office. <br>\n\n<br>\nRelative thereto, please click link below a copy of the findings and recommendations of our technical evaluators \nfor the said application. Kindly proceed to our office, retrieve your submitted documents, \nand make the necessary corrections based on our findings and recommendations. \nAfterwhich, please return the complete documents with the necessary corrections to our office for us to continue the \nre-evaluation and processing of your application. <br>\n<br>\n<br>\nPlease see attached file.\n<br>\nThank you. <br>\n<br>\n<br>\nSincerely,\n<br>\n<b>The Gensan OSCP Team</b>','${email}',NULL,'obo-email-server',NULL,'PARAMS.appid = \"BAPP-67bb8cf:17a32c2e74f:-7efa\";\nPARAMS.email = \"elmonazareno@gmail.com\";','${emailcopy}'),('obo_app_doc','def docEm = EM.lookup( \"vw_obo_app_doc\" );\ndef doc = docEm.find( [objid: PARAMS.objid]  ).first();\n\ndef r = [:];\nr.title = doc.doctype?.title;\nr.appno = doc.app?.appno;\nr.email =  (!PARAMS.email) ? doc.app?.contact?.email : PARAMS.email;\nr.attachments = [  \n    [reportid: doc.reportid, params: [objid: PARAMS.objid], context: \'obo\', title: r.title + \".pdf\"  ] \n];\nreturn r;\n','App ${appno} ${title}','Please View Attachments for ${title} <br>\n\n','${email}',NULL,'obo-email-server',NULL,'PARAMS.objid = \"BASUBDOC-4a4aff96:17a564ead0d:-77b1\";\nPARAMS.email = \"elmonazareno@gmail.com\";',NULL),('obo_bill','def em = EM.lookup( \"vw_obo_app\" );\ndef app = em.find( [objid: PARAMS.objid] ).first();\nif(!app.billid) throw new Exception(\"Error message template obo_bill. billid does not exist\");\ndef res = [:];\nres.email = (!PARAMS.email) ? app.contact?.email : PARAMS.email;\nres.contact = app.contact;\nres.appno = app.appno;\nres.trackingno = app.trackingno;\nres.doctitle = app.doctitle;\nres.attachments = [\n     [ reportid: \'obo_bill\', params: [objid: app.billid ], context:\'obo\', title: \'Tax Order of Payment\' ]\n];\nreturn res;','Tax Order for Payment ${doctitle} ${appno}','Your tax order of payment is ready for tracking no. ${trackingno} <br>\n\nPlease see attached billing','${email}',NULL,'obo-email-server',NULL,'PARAMS.objid = \"BAPP-18112266:18ba451d2b6:-8000\";\nPARAMS.email = \"elmonazareno@gmail.com\";',NULL),('occupancy_certificate','def svc = SERVICE.lookup(\"SysReportGeneratorService\");\ndef app = EM.lookup( \"vw_obo_app\" ).find( [ objid: PARAMS.appid ] ).first();\ndef em = EM.lookup( \"vw_obo_app_doc\" );\ndef doclist = em.find( [appid: PARAMS.appid] ).where(\"doctype.type = \'MAIN\' AND doctype.includeinemail=1\").orderBy( \"doctype.sortorder ASC\" ).list();\n\napp.attachments = [];\ndoclist.each {\n   def url = svc.buildWebUrl(  [reportid: it.reportid, objid: it.objid ] );\n   app.attachments << [ title: it.doctype.title, url: url ];	\n}\n\nreturn app;','Occupancy Certificate Approved - ${appno}','Dear ${contact.name}, <br>\n\nYour occupancy certificate with application no <b>${appno}</b> has been approved. You may view the advanced copies of your documents as follows: <br>\n\n<% attachments.each { o-> %>\n     <li><a href=\"${o.url}\">${o.title}</a></li>\n<% } %>\n\nSincerely,<br>\nThe Gensan OSCP Team','contact.email',NULL,'obo-email-server',NULL,NULL,NULL),('occupancy_certificate_docs','def em = EM.lookup( \"vw_obo_app\" );\ndef docEm = EM.lookup( \"vw_obo_app_doc\" );\ndef app = em.find( [objid: PARAMS.objid] ).first();\napp.email = (!PARAMS.email) ? app.contact.email : PARAMS.email ;\n\napp.attachments = docEm.find( [appid: PARAMS.objid]  ).where( \"doctype.includeinemail = 1\" ).list().collect {\n     [  reportid: it.reportid, params: [ objid: it.objid ], title: it.doctype.title, context: \'obo\' ]\n}\nreturn app;','Occupancy Certificate','Dear ${contact.name}, <br>\nYour Occupancy Certificate  application with the ff. has been approved. \n<h1>${appno}</h1>\n\nPlease see advanced copies of permits.\n','${email}',NULL,'obo-email-server',NULL,NULL,NULL),('test-mail','def app = [:];\napp.email = \"rojanpaics@gmail.com\"\napp.cc = \"rojanpaics@yahoo.com\"\napp.contact = [name: \"Rojan\"]\nreturn app;','Test Mail - ${email}','<b>Hello ${contact.name}</b>\n','${email},${cc}',NULL,'obo-email-server',NULL,NULL,'${cc}');
