INSERT INTO `sys_report_def` VALUES ('approved_building_permit_list','Approved Building Permit List','reports','approved_building_permit_list','OBO_HEADER',NULL,1,'SELECT\n   pmt.controlno AS permitno,\n   a.appno,\n   DATE_FORMAT(a.appdate, \'%Y-%m-%d\' ) AS dtreceived, \n   ae.name AS applicant_name,\n   ae.address_text AS address_text,\n   og.title AS occupancytype_title,\n   a.txntype,\n   DATE_FORMAT(t.dtcreated, \'%Y-%m-%d\') AS dtcompleted, \n   ps.obo_lgu_fee,\n   ps.obo_obo_fee,\n   ps.obo_dpwh_fee,\n   ps.zoning_fee,\n   ps.bfp_fee,\n   ps.casso_fee,\n   MONTH( t.dtcreated ) AS bmonth,\n   YEAR( t.dtcreated ) AS byear\n\nFROM obo_app a \nINNER JOIN obo_appclass clz ON a.appclassid = clz.objid \nINNER JOIN building_permit bp ON a.objid = bp.objid \nINNER JOIN obo_app_task t ON a.taskid = t.taskid \nINNER JOIN obo_app_entity ae ON a.applicantid = ae.objid\nINNER JOIN sys_wf_node sn ON sn.processname = clz.processname AND sn.name = t.state \nINNER JOIN obo_occupancy_type bt ON bp.occupancytypeid = bt.objid \nINNER JOIN obo_occupancy_type_division od ON bt.divisionid = od.objid \nINNER JOIN obo_occupancy_type_group og ON od.groupid = og.objid \nINNER JOIN obo_app_doc adoc ON adoc.appid = a.objid \nINNER JOIN obo_control pmt ON adoc.controlid = pmt.objid  \nINNER JOIN (\n    SELECT z.appid,\n      SUM(z.obo_fee) AS obo_fee, \n      (SUM(z.obo_fee)*0.80) AS obo_lgu_fee,\n      (SUM(z.obo_fee)*0.15) AS obo_obo_fee,\n      (SUM(z.obo_fee)*0.05) AS obo_dpwh_fee,\n      SUM(z.zoning_fee) AS zoning_fee,\n      SUM(z.bfp_fee) AS bfp_fee,\n      SUM(z.casso_fee) AS casso_fee\n   FROM \n   (SELECT\n      f.appid, \n      CASE WHEN i.feegroupid = \'BLDG_PERMIT\' THEN f.amount ELSE 0 END AS obo_fee,\n      CASE WHEN i.feegroupid = \'ZONING\' THEN f.amount ELSE 0 END AS zoning_fee,\n      CASE WHEN i.feegroupid = \'BFP\' THEN f.amount ELSE 0 END AS bfp_fee,\n      CASE WHEN i.feegroupid = \'OTHER\' THEN f.amount ELSE 0 END AS casso_fee\n   FROM obo_app_fee f \n   INNER JOIN obo_itemaccount i ON f.itemid = i.objid  \n   ) z\n   GROUP BY z.appid \n) ps ON ps.appid = a.objid  \n \nWHERE t.state = \'end\' AND MONTH( t.dtcreated )  = $P{ bmonth } AND YEAR( t.dtcreated ) = $P{ byear }\nORDER BY pmt.controlno\n',NULL,'[[prompt:1,name:\"bmonth\",caption:\"Month\",type:\"monthlist\"],[prompt:1,name:\"byear\",caption:\"Year\",type:\"integer\"]]','SQL','DEPLOYED',NULL,'[]',NULL,NULL,NULL),('approved_occupancy_certificate_list','Approved Occupancy Certificates','reports','approved_occupancy_certificate_list','OBO_HEADER',NULL,2,'SELECT\n   pmt.controlno AS permitno,\n   a.appno,\n   DATE_FORMAT(a.appdate, \'%Y-%m-%d\' ) AS dtreceived, \n   ae.name AS applicant_name,\n   ae.address_text AS address_text,\n   og.title AS occupancytype_title,\n   a.txntype,\n   DATE_FORMAT(t.dtcreated, \'%Y-%m-%d\') AS dtcompleted, \n   ps.obo_lgu_fee,\n   ps.obo_obo_fee,\n   ps.obo_dpwh_fee,\n   ps.bfp_fee,\n   MONTH( t.dtcreated ) AS bmonth,\n   YEAR( t.dtcreated ) AS byear\n\nFROM obo_app a \nINNER JOIN occupancy_certificate oc ON a.objid = oc.objid \nINNER JOIN obo_app_task t ON a.taskid = t.taskid \nINNER JOIN obo_app_entity ae ON a.applicantid = ae.objid\nINNER JOIN sys_wf_node sn ON sn.processname = \'occupancy_certificate\' AND sn.name = t.state \nINNER JOIN obo_occupancy_type bt ON oc.occupancytypeid = bt.objid \nINNER JOIN obo_occupancy_type_division od ON bt.divisionid = od.objid \nINNER JOIN obo_occupancy_type_group og ON od.groupid = og.objid \nINNER JOIN obo_app_doc adoc ON adoc.appid = a.objid \nINNER JOIN obo_control pmt ON adoc.controlid = pmt.objid  \n\nINNER JOIN (\n    SELECT z.appid,\n      (SUM(z.obo_fee)*0.80) AS obo_fee, \n      (SUM(z.obo_fee)*0.80) AS obo_lgu_fee,\n      (SUM(z.obo_fee)*0.15) AS obo_obo_fee,\n      (SUM(z.obo_fee)*0.05) AS obo_dpwh_fee,\n      SUM(z.bfp_fee) AS bfp_fee\n   FROM \n   (SELECT\n      f.appid, \n      CASE WHEN i.feegroupid = \'BLDG_PERMIT\' THEN f.amount ELSE 0 END AS obo_fee,\n      CASE WHEN i.feegroupid = \'BFP\' THEN f.amount ELSE 0 END AS bfp_fee\n   FROM obo_app_fee f \n   INNER JOIN obo_itemaccount i ON f.itemid = i.objid  \n   ) z\n   GROUP BY z.appid \n) ps ON ps.appid = a.objid  \nWHERE t.state = \'end\' AND MONTH( t.dtcreated )  = $P{ bmonth } AND YEAR( t.dtcreated ) = $P{ byear }\nORDER BY pmt.controlno\n',NULL,'[[prompt:1,name:\"bmonth\",caption:\"Month\",type:\"monthlist\"],[prompt:1,name:\"byear\",caption:\"Year\",type:\"integer\"]]','SQL','DEPLOYED',NULL,'[]',NULL,NULL,NULL),('barangay_clearance','Barangay Clearance','obo_app_doc','barangay_clearance',NULL,NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\n\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \n//def evaluator = svc.getEvaluatorSignatory( [ appid: doc.appid, sectionid: doc.sectionid] );\n\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname:\"vw_building_permit\" ] );\nbp.putAll( doc );\nbp.putAll( signatory ); \nbp.putAll( qrcode );\nbp.putAll( rct );\n//bp.putAll( evaluator );\n\nif( doc.doctype.reportheader ) {\n      bp.HEADER = svc.getReportHeaders( [name: doc.doctype.reportheader] );\n}\nreturn bp ;',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid = \"BASUBDOC78c11597:18c0ef901e2:-8000\" ;',NULL),('building_permit','Building Permit','obo_app_doc','building_permit','OBO_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\n\ndef fsvc = SERVICE.lookup( \"OboAppFindingService\" );\ndef postreqList = fsvc.getOpenPostRequirementList( [ appid: doc.appid  ] );\n\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname:\"vw_building_permit\" ] );\ndef rpus = svc.getRpus( [appid:  doc.appid ] );\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \ndoc.putAll( bp ); \ndoc.putAll( rpus );\ndoc.putAll( qrcode );\ndoc.putAll( rct );\ndoc.putAll( signatory );\ndoc.fsec = svc.getRelatedDoc( [appid: doc.appid, doctypeid: \"FSEC\" ]);\ndoc.postreqlist = postreqList*.particulars.join( \"<br>\" );\nif( doc.doctype.reportheader ) {\n      doc.HEADER = svc.getReportHeaders( [name: doc.doctype.reportheader] );\n}\nreturn doc;',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid=\'BASUBDOC-415accb6:18c85bbe2f3:-7ffc\';',NULL),('building_permit_signage','Building Permit Signage','obo_app:reports','building_permit_signage','OBO_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\ndef bp = svc.getAppData( [ appid: PARAMS.objid , schemaname:\"vw_building_permit\" ] );\ndef profs = svc.getProfessionals( [appid: PARAMS.objid ] );\nbp.putAll( profs );\nreturn bp;\n\n',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid = \"BAPP-67bb8cf:17a32c2e74f:-7efa\";','#{ task.state.matches( \'releasing|for-pickup|end\' ) }'),('claimstub','Claim Stub','obo_app:reports','claimstub','OBO_HEADER',NULL,1,'def appEm = EM.lookup( \"vw_obo_app\" );\ndef app = appEm.find(  [ objid: PARAMS.objid ] ).first();\nif( !app.appno) \n    throw new Exception(\"Appno not found\"); \n\n/* determine the receiver. it is the last received/reactivated  */\ndef tskEm = EM.lookup(  \"obo_app_task\"  );\ndef tsk = tskEm.find( [refid: app.objid] ).where( \"state = \'requirement-verification\' \").orderBy(\"dtcreated DESC\").first();\n\napp.dtreceived = tsk?.enddate;\napp.receiver = [ name: tsk?.assignee?.name ];\napp.permittype = app.doctitle;\nreturn app;\n\n',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid	= \'BAPP-5c99bf5c:182f7af3262:-7f0e\';','#{ entity.appno != null }'),('dpwh_report','DPWH Report','reports','dpwh_report','OBO_HEADER',NULL,1,'SELECT\n   pmt.controlno AS permitno,\n   a.appno,\n   DATE_FORMAT(a.appdate, \'%Y-%m-%d\' ) AS dtreceived, \n   ae.name AS applicant_name,\n   ae.address_text AS address_text,\n   og.title AS occupancytype_title,\n   a.txntype,\n   DATE_FORMAT(t.dtcreated, \'%Y-%m-%d\') AS dtcompleted, \n   MONTH( t.dtcreated ) AS bmonth,\n   YEAR( t.dtcreated ) AS byear\n\nFROM obo_app a \nINNER JOIN building_permit bp ON a.objid = bp.objid \nINNER JOIN obo_app_task t ON a.taskid = t.taskid \nINNER JOIN obo_app_entity ae ON a.applicantid = ae.objid\nINNER JOIN sys_wf_node sn ON sn.processname = \'building_permit\' AND sn.name = t.state \nINNER JOIN obo_occupancy_type bt ON bp.occupancytypeid = bt.objid \nINNER JOIN obo_occupancy_type_division od ON bt.divisionid = od.objid \nINNER JOIN obo_occupancy_type_group og ON od.groupid = og.objid \nINNER JOIN obo_app_doc adoc ON adoc.appid = a.objid \nINNER JOIN obo_control pmt ON adoc.controlid = pmt.objid  \n\nWHERE t.state = \'end\' AND MONTH( t.dtcreated )  = $P{ bmonth } AND YEAR( t.dtcreated ) = $P{ byear }\nORDER BY pmt.controlno\n',NULL,'[[prompt:1,name:\"bmonth\",caption:\"Month\",type:\"monthlist\"],[prompt:1,name:\"byear\",caption:\"Year\",type:\"integer\"]]','SQL','DEPLOYED',NULL,'[]',NULL,NULL,NULL),('final_electrical_inspection','Certificate of Final Electrical Inspection','obo_app_doc','final_electrical_inspection','OBO_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname: doc.app.schemaname ] );\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\ndef infos = svc.getDocInfos(   [objid: doc.objid] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \ndef evaluator = svc.getEvaluatorSignatory( [ appid: doc.appid, sectionid:doc.sectionid] );\ndef prof = svc.getSupervisor([ appid: doc.appid,sectionid: doc.sectionid ]);\ndoc.putAll( bp ); \ndoc.putAll( qrcode );\ndoc.putAll( rct );\ndoc.putAll( infos );\ndoc.putAll( signatory );\ndoc.putAll( evaluator );\ndoc.electrical=[supervisor:prof];\nif( doc.doctype.reportheader ) {\n      doc.HEADER = svc.getReportHeaders( [name: doc.doctype.reportheader] );\n}\nreturn doc;\n',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid=\'BASUBDOC5cef03c0:18a02170956:-517b\';',NULL),('fsec','FSEC','obo_app_doc','fsec','BFP_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\n\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \ndef evaluator = svc.getEvaluatorSignatory( [ appid: doc.appid, sectionid: doc.sectionid] );\n\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\n\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname:\"vw_building_permit\" ] );\nbp.putAll( doc );\nbp.putAll( signatory ); \nbp.putAll( qrcode );\nbp.putAll( rct );\nbp.putAll( evaluator );\nif( doc.doctype.reportheader ) {\n      bp.HEADER = svc.getReportHeaders( [name: doc.doctype.reportheader] );\n}\nreturn bp;',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid = \"BASUBDOC63bbe24d:17fd30115d8:-7cac\";',NULL),('fsec_checklist','FSEC Checklist','obo_app_doc','fsec_checklist','BFP_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\ndef chklist = svc.getDocChecklist( [objid: doc.objid] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \ndef evaluator = svc.getEvaluatorSignatory( [ appid: doc.appid, sectionid: doc.sectionid] );\n\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\n\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname:\"vw_building_permit\" ] );\ndef fsec = svc.getRelatedDoc( [appid: doc.appid, doctypeid: \"FSEC\" ]);\n\nbp.putAll( doc );\nbp.putAll( signatory );\nbp.putAll( chklist ); \nbp.putAll( qrcode );\nbp.putAll( rct );\nbp.putAll( evaluator );\nbp.amount = fsec.amount;\nbp.dtreceived = evaluator.dtevaluated;\nif( doc.doctype.reportheader ) {\n      bp.HEADER = svc.getReportHeaders( [name: doc.doctype.reportheader] );\n}\nreturn bp ;',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid = \"BASUBDOC317bdd3:183771a8a86:-87f\";',NULL),('fsec_checklist2','FSEC Checklist 2','obo_app_doc','fsec_checklist2','BFP_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\n\ndef chklist = svc.getDocAllChecklist( [objid: doc.objid, checklistid: doc.checklistid ] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \ndef evaluator = svc.getEvaluatorSignatory( [ appid: doc.appid, sectionid: doc.sectionid] );\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname:\"vw_building_permit\" ] );\ndef fsec = svc.getRelatedDoc( [appid: doc.appid, doctypeid: \"FSEC\" ]);\nbp.putAll( doc );\nbp.putAll( signatory );\nbp.putAll( chklist ); \nbp.putAll( qrcode );\nbp.putAll( rct );\nbp.putAll( evaluator );\nbp.amount = fsec.amount;\nbp.dtreceived = evaluator.dtevaluated;\nif( doc.doctype.reportheader ) {\n      bp.HEADER = svc.getReportHeaders( [name: doc.doctype.reportheader] );\n}\nreturn bp ;',NULL,'[]','SCRIPT','DEPLOYED',NULL,'[]',NULL,'PARAMS.objid = \"BASUBDOC5b68a735:18c0ed41179:-8000\";',NULL),('fsic','Fire Safety Inspection Certificate','obo_app_doc','fsic','BFP_HEADER',NULL,1,'def svc = SERVICE.lookup( \"OboAppDocFormReportService\" );\n\ndef doc = svc.getDocData( [objid:  PARAMS.objid ] );\ndef qrcode = svc.getQrCode( [objid: doc.objid] );\ndef signatory = svc.getDocSignatory( [doctypeid: doc.doctypeid] ); \ndef inspector = svc.getInspectorSignatory( [ appid: doc.appid, sectionid: doc.sectionid] ); \n\ndef rct = svc.getReceipt( [ appid: doc.appid ] );\n\ndef bp = svc.getAppData( [ appid: doc.appid, schemaname:\"vw_occupancy_certificate\" ] );\nbp.putA