fe','\npackage oboassessment.SPECIAL_LOCATIONAL_CLEARANCE;\nimport oboassessment.*;\nimport java.util.*;\nimport com.rameses.rules.common.*;\n\nglobal RuleAction action;\n\nrule \"SPECIAL_LOCATIONAL_CLEARANCE\"\n	agenda-group \"compute-zoning-fee\"\n	salience 100000\n	no-loop\n	when\n		\n		\n		 obo.facts.BuildingInfo (  COST:projectcost ) \n		\n		 obo.facts.OccupancyType (  type matches \"E102|E220\" ) \n		\n		BD: obo.facts.OboDocument (  doctype matches \"LOCATIONAL_CLEARANCE\" ) \n		\n	then\n		Map bindings = new HashMap();\n		\n		bindings.put(\"COST\", COST );\n		\n		bindings.put(\"BD\", BD );\n		\n	RangeEntry re0 = new RangeEntry(\"SPECIAL_LOCATIONAL_CLEARANCE\");\nre0.setBindings(bindings);\nre0.setDecimalvalue(COST);\nre0.getParams().put( \"amount\", 0.0 );\nre0.getParams().put( \"billcode\", new KeyValue(\"LOCATIONAL_CLEARANCE_FEE\", \"LOCATIONAL CLEARANCE FEE\") );\ninsert(re0);\n\nend\n\n\n	\nrule \"add-billitem_0_0\"\n	agenda-group \"compute-zoning-fee\"\n	salience 100000\n	no-loop\n	when\n		\n		\n		\n		rv: RangeEntry( id==\"SPECIAL_LOCATIONAL_CLEARANCE\", decimalvalue < 2000000.00 )\n		\n	then\n		Map bindings = rv.getBindings();\n		Map params = rv.getParams();\n		params.put( \"amount\", (new ActionExpression(\"7200\", bindings)) );	\n		 \n		action.execute( \"add-billitem\",params, drools);\nend\n\n\n	\nrule \"add-billitem_0_1\"\n	agenda-group \"compute-zoning-fee\"\n	salience 100000\n	no-loop\n	when\n		\n		\n		rv: RangeEntry( id==\"SPECIAL_LOCATIONAL_CLEARANCE\", decimalvalue >= 2000000.00 )\n		\n		\n	then\n		Map bindings = rv.getBindings();\n		Map params = rv.getParams();\n		params.put( \"amount\", (new ActionExpression(\"8000 + (( COST-2000000) * 0.10 * 0.01 )\", bindings)) );	\n		 \n		action.execute( \"add-billitem\",params, drools);\nend\n\n\n	'),('RUL-29595738:16a4fbe79ee:-7bd1','\npackage oboassessment.COMMERCIAL_INDUSTRIAL_LOCATIONAL_CLEARANCE;\nimport oboassessment.*;\nimport java.util.*;\nimport com.rameses.rules.common.*;\n\nglobal RuleAction act