rt com.rameses.rules.common.*;\n\nglobal RuleAction action;\n\nrule \"BARANGAY_APOPONG\"\n	agenda-group \"barangay-docs\"\n	salience 50000\n	no-loop\n	when\n		\n		\n		 obo.facts.OboApp (  type matches \"BUILDING_PERMIT\" ) \n		\n		 obo.facts.BuildingInfo (  BRGY:barangayid matches \"000-01-0002\" ) \n		\n	then\n		Map bindings = new HashMap();\n		\n		bindings.put(\"BRGY\", BRGY );\n		\n	Map _p0 = new HashMap();\n_p0.put( \"doctype\", new KeyValue(\"CLEARANCE_BUAYAN\", \"CLEARANCE BUAYAN\") );\naction.execute( \"add-obo-document\",_p0,drools);\n\nend\n\n\n	'),('RULb3b305a:176400527ad:-6969','\npackage oboassessment.FINAL_ELECTRICAL_INSPECTION_FEE;\nimport oboassessment.*;\nimport java.util.*;\nimport com.rameses.rules.common.*;\n\nglobal RuleAction action;\n\nrule \"FINAL_ELECTRICAL_INSPECTION_FEE\"\n	agenda-group \"compute-inspection-fee\"\n	salience 50000\n	no-loop\n	when\n		\n		\n		DOC: obo.facts.OboDocument (  doctype matches \"FINAL_ELECTRICAL_INSPECTION\" ) \n		\n	then\n		Map bindings = new HashMap();\n		\n		bindings.put(\"DOC\", DOC );\n		\n	Map _p0 = new HashMap();\n_p0.put( \"amount\", (new ActionExpression(\"100\", bindings)) );\n_p0.put( \"billcode\", new KeyValue(\"FINAL_ELECTRICAL_INSPECTION_FEE\", \"FINAL ELECTRICAL INSPECTION FEE\") );\naction.execute( \"add-billitem\",_p0,drools);\n\nend\n\n\n	');
